-- United Arab Emirates deep-dive content: page, stats, 4 file_format cards,
-- 3 scope_transmission cards + 1 lifecycle card ('The five corners', a genuine
-- sequential DCTCE flow -- unlike Saudi Arabia's QR-code tag list, this one is a real
-- process, and sits in scope_transmission per the usual pattern), 6 steps, a genuine
-- 6-row tabular penalty schedule + 3 narrative penalties_related cards (both at once,
-- per Belgium/Italy/Saudi precedent), 1 portal.

INSERT OR IGNORE INTO deep_dive_pages (country_id, last_updated) SELECT id, '2026-07-21' FROM countries WHERE name_en = 'United Arab Emirates';
INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro) SELECT id, 'en', 'Decentralised 5-corner (DCTCE)', 'This deep-dive page reflects publicly available technical guidance as of July 2026 and is provided for general awareness, not legal or tax advice. PINT AE technical specifications, the ASP accreditation register, and penalty enforcement continue to evolve — confirm current requirements directly with the UAE Ministry of Finance or Federal Tax Authority before building an integration.', 'The UAE built its e-invoicing framework unusually methodically — data dictionary consultation, then legislation, then ASP accreditation, then a voluntary pilot, all before the mandate itself begins.', 'PINT AE is a genuinely large specification — over 135 data elements, layered deliberately to balance global Peppol interoperability with UAE-specific VAT rules.', 'The UAE''s "5-corner" DCTCE model bundles Peppol-style exchange with automatic tax reporting — there''s no separate VAT filing step for e-invoiced transactions.', 'Don''t assume your ASP alone handles everything — internal IT and finance alignment is explicitly called out as a common gap.', 'Cabinet Decision No. 106 of 2025 defines six specific violation categories — some capped monthly, others accumulating daily without limit.' FROM countries WHERE name_en = 'United Arab Emirates';

