INSERT OR IGNORE INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 0 FROM countries WHERE name_en = 'United Arab Emirates';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'en', 'What PINT AE is', '[["Full meaning", "Peppol International (UAE)"], ["Base standard", "UBL, aligned with global Peppol PINT"], ["Legal adoption", "Ministerial Decision No. 243 of 2025"]]', 'PINT AE is a localised extension, not a wholly separate schema — businesses already familiar with Peppol PINT elsewhere have a genuine head start.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'United Arab Emirates' AND dc.section = 'file_format' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 1 FROM countries WHERE name_en = 'United Arab Emirates';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'en', 'Three content layers', '[["Shared Core Content", "Universal Peppol PINT elements (IDs, dates, parties, totals)"], ["Aligned Content", "Internationally standardised fields mapped to UAE classifications (VAT categories, tax logic, payment)"], ["UAE Extension", "UAE-specific fields beyond the global baseline"]]', 'This layered design is exactly what preserves baseline interoperability across the global Peppol network while still enforcing UAE-specific VAT rules.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'United Arab Emirates' AND dc.section = 'file_format' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 2 FROM countries WHERE name_en = 'United Arab Emirates';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'en', 'Field count & scope', '[["Total elements", "135+ (mandatory, conditional, optional)"], ["Standard tax invoice", "~50–51 mandatory fields"], ["Supported scenarios", "Standard, zero-rated, reverse charge, free zone supplies"]]', 'Missing or incorrectly formatted mandatory fields cause outright rejection with no manual override — there''s no partial acceptance or manual correction step at the ASP layer.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'United Arab Emirates' AND dc.section = 'file_format' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 3 FROM countries WHERE name_en = 'United Arab Emirates';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'en', 'Key identifiers & content', '[["UUID", "Unique per invoice document"], ["Line-level", "VAT rate and amount per line item"], ["Currency", "Total invoice amount in AED"], ["Security", "Digital signature (applied by the ASP) + QR code"]]', 'PDFs, scanned documents, and paper invoices are explicitly not valid under the mandate — only structured XML/JSON generated to PINT AE counts.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'United Arab Emirates' AND dc.section = 'file_format' AND dc.sort_order = 3;

INSERT OR IGNORE INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'scope_transmission', 0 FROM countries WHERE name_en = 'United Arab Emirates';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'en', 'What your ASP actually does', '[["Validation", "Checks XML against the PINT AE schema"], ["Conversion", "Converts invoicing data to compliant PINT AE XML"], ["Security", "Applies digital signature and QR code"], ["Transmission", "Sends over the Peppol network to the buyer''s ASP"]]', 'Your ERP only needs to generate the underlying invoice data — the ASP handles conversion, signing, and delivery, but that division of labour means choosing the right ASP genuinely matters.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'United Arab Emirates' AND dc.section = 'scope_transmission' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'scope_transmission', 1 FROM countries WHERE name_en = 'United Arab Emirates';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'en', 'ASP accreditation process', '[["1. Application", "Submitted via the MoF portal"], ["2–3. Testing", "Pre-approval interoperability checks, then production end-to-end testing"], ["4. Certification", "ISO certificate, insurance, and compliance verification"], ["5. Credential", "Peppol PKI certificate issuance"], ["6. Accreditation", "Granted for 2 years, renewable"]]', 'Always verify a provider''s accreditation against the MoF''s official public register directly — don''t rely on a provider''s own marketing claim of accreditation.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'United Arab Emirates' AND dc.section = 'scope_transmission' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'scope_transmission', 2 FROM countries WHERE name_en = 'United Arab Emirates';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'en', 'No direct FTA portal upload', '[["Model", "Decentralised — invoices flow via Peppol/ASP, never directly to a government portal"]]', 'This is the defining contrast with Saudi Arabia next door: there''s no government clearance portal to upload to — everything routes through your accredited service provider.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'United Arab Emirates' AND dc.section = 'scope_transmission' AND dc.sort_order = 2;

