INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'en', '🕊️ Voluntary participants exempt', NULL, NULL, 'Businesses using the system voluntarily during the pilot phase are not subject to these penalties until they become mandatorily subject to e-invoicing — a genuine risk-free window to test.', NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'United Arab Emirates' AND dc.section = 'penalties_related' AND dc.sort_order = 0;
