INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'en', '⚠️ Dual penalty exposure', NULL, NULL, 'E-invoicing failures can also trigger broader tax violation penalties under Cabinet Decision No. 129 of 2025 — for example, invoice data gaps leading to inaccurate VAT return figures carry their own separate percentage-based penalties on top of the CD 106 fines.', NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'United Arab Emirates' AND dc.section = 'penalties_related' AND dc.sort_order = 1;
